import{_ as t,o as n,c as e,a2 as s}from"./chunks/framework.A5mep7Fe.js";const u=JSON.parse('{"title":"🏗️ 01 · AI 应用架构","description":"","frontmatter":{},"headers":[],"relativePath":"08-AI应用开发/01-AI应用架构.md","filePath":"08-AI应用开发/01-AI应用架构.md","lastUpdated":1786806808000}'),l={name:"08-AI应用开发/01-AI应用架构.md"};function i(o,a,r,p,d,h){return n(),e("div",null,[...a[0]||(a[0]=[s(`<h1 id="🏗️-01-·-ai-应用架构" tabindex="-1">🏗️ 01 · AI 应用架构 <a class="header-anchor" href="#🏗️-01-·-ai-应用架构" aria-label="Permalink to &quot;🏗️ 01 · AI 应用架构&quot;">​</a></h1><blockquote><p>一个生产级 AI 应用长什么样？如何选型？私有化还是云？本篇给全局视图。</p></blockquote><hr><h2 id="一、典型分层架构" tabindex="-1">一、典型分层架构 <a class="header-anchor" href="#一、典型分层架构" aria-label="Permalink to &quot;一、典型分层架构&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>接入层：Web/App/API/IM 机器人</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>网关层：鉴权 · 限流 · 成本统计 · 模型路由 · 降级</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>编排层：Prompt 管理 · RAG · Agent · 多轮对话状态</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>模型层：LLM（自部署 vLLM / 云 API）· Embedding · 重排 · 多模态</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>数据层：向量库 · 关系库 · 对象存储 · 文档 ETL</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>支撑：可观测 · 评测闭环 · 缓存 · 异步任务</span></span></code></pre></div><h2 id="二、关键技术决策" tabindex="-1">二、关键技术决策 <a class="header-anchor" href="#二、关键技术决策" aria-label="Permalink to &quot;二、关键技术决策&quot;">​</a></h2><h3 id="_1-模型从哪来" tabindex="-1">1. 模型从哪来？ <a class="header-anchor" href="#_1-模型从哪来" aria-label="Permalink to &quot;1. 模型从哪来？&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方式</th><th>优点</th><th>缺点</th><th>适用</th></tr></thead><tbody><tr><td>云 API（GPT/Claude/Qwen云）</td><td>快、免运维、能力强</td><td>数据出域、按量付费、不可微调</td><td>快速验证、非敏感</td></tr><tr><td>自部署开源（vLLM+Qwen/DeepSeek）</td><td>数据私有、可控成本</td><td>需 GPU/运维</td><td>数据敏感、规模大</td></tr><tr><td>混合</td><td>主力闭源 + 开源兜底</td><td>复杂</td><td>生产稳健</td></tr></tbody></table><h3 id="_2-私有化-vs-公有云" tabindex="-1">2. 私有化 vs 公有云 <a class="header-anchor" href="#_2-私有化-vs-公有云" aria-label="Permalink to &quot;2. 私有化 vs 公有云&quot;">​</a></h3><ul><li>数据合规/隐私要求高（金融/政企/医疗）→ 私有化（信创、离线）</li><li>初创/快速验证 → 公有云起步，后迁移</li></ul><h3 id="_3-框架选型" tabindex="-1">3. 框架选型 <a class="header-anchor" href="#_3-框架选型" aria-label="Permalink to &quot;3. 框架选型&quot;">​</a></h3><ul><li><strong>轻量自研核心循环</strong>：多数场景够用、可控、易调试</li><li><strong>LangChain/LlamaIndex</strong>：快速原型，但生产注意抽象开销</li><li>不要为了用框架而用框架</li></ul><h2 id="三、常见反模式-避坑" tabindex="-1">三、常见反模式（避坑） <a class="header-anchor" href="#三、常见反模式-避坑" aria-label="Permalink to &quot;三、常见反模式（避坑）&quot;">​</a></h2><ul><li>把全部逻辑塞进一个超长 Prompt</li><li>无降级：模型挂则全站挂</li><li>无缓存：重复请求狂烧钱</li><li>无评测：改 Prompt 不知道变好变坏</li><li>忽视安全：工具调用无权限、RAG 越权</li></ul><h2 id="四、高频追问" tabindex="-1">四、高频追问 <a class="header-anchor" href="#四、高频追问" aria-label="Permalink to &quot;四、高频追问&quot;">​</a></h2><p><strong>Q1：什么时候该自部署而不是调 API？</strong></p><blockquote><p>数据敏感/合规要求、调用量大到 API 成本过高、需微调/定制、需离线运行。否则先用 API 快速验证 PMF 更划算。</p></blockquote><p><strong>Q2：AI 应用架构最易漏的环节？</strong></p><blockquote><p>可观测与评测闭环、降级与成本治理、安全与权限。demo 阶段都无所谓，一上生产就爆。</p></blockquote><hr><p>➡️ 下一步：<a href="./02-向量数据库与RAG工程">02-向量数据库与RAG工程</a></p>`,21)])])}const b=t(l,[["render",i]]);export{u as __pageData,b as default};
